"""Reproducible all-topic shipping inventory; no title-based content mapping."""
import json
from collections import Counter
from app.config import REPO_ROOT
from app.services.content_registry import digest
from scripts.placement_batch import ROOT


def inventory():
    scope=json.loads((REPO_ROOT/"data/placement-foundations-scope.json").read_text(encoding="utf-8"))
    sources={s["subject"]:s for s in json.loads((ROOT/"sources.json").read_text(encoding="utf-8"))["sources"]}
    rows=[]
    for topic in scope["topics"]:
        key=topic["key"];lesson=ROOT/"candidates"/(key+".lesson.json");assessment=ROOT/"candidates"/(key+".assessment.json")
        candidates=[p for p in [lesson,assessment] if p.exists()]
        validated=[];errors=[];items=[]
        for path in candidates:
            value=json.loads(path.read_text(encoding="utf-8"));report=ROOT/"validation"/(path.stem+".validation.json")
            if report.exists():
                result=json.loads(report.read_text(encoding="utf-8"))
                if digest(__import__('app.schemas.publication',fromlist=['Candidate']).Candidate.model_validate(value).model_dump(mode="json"))==result["candidate_sha256"] and result.get("executable_checks_passed"):
                    validated.append(path.name)
                else:errors.append("Stale/failed validation: "+path.name)
            else:errors.append("Validation missing: "+path.name)
            if value["content_type"]=="assessment_bundle":items=value["payload"]["assessment"]["items"]
        if not lesson.exists():errors.append("Teaching not authored")
        if not assessment.exists():errors.append("Assessment pool not authored")
        errors.append("Independent human review and publication pending")
        # A subject-level legacy corpus is a reference for an editor. It is not a
        # claim that any of its lessons covers this scope topic, nor a runtime binding.
        historical=sorted(p.relative_to(REPO_ROOT).as_posix() for p in (REPO_ROOT/"content/ai-engineer/v1"/topic["subject_key"]).glob("*/lesson.json"))
        depths={purpose:sum(purpose in item["purposes"] and item["kind"]!="reflection" for item in items)
                for purpose in ["practice","transfer","recall","interview"]}
        rows.append({"topic_key":key,"subject":topic["subject_key"],"level":topic["level"],"title":topic["title"],
            "competencies_required":topic["coverage_requirements"],"learning_outcomes":topic["learning_outcomes"],"prerequisites":topic["prerequisites"],
            "historical_material":{"subject_corpus":historical,"reviewed_topic_mapping":None,"reuse_status":"not_mapped; independent coverage/provenance review required"},
            "new_lesson_required":not lesson.exists(),"lesson_bundle_status":"candidate" if lesson.exists() else "not_authored",
            "candidate_paths":[p.relative_to(REPO_ROOT).as_posix() for p in candidates],
            "source_provenance":{"registered_references":[sources[topic["subject_key"]]],"topic_claim_review":"pending"},
            "candidate_pool_depth":depths,"published_pool_depth":{purpose:0 for purpose in depths},
            "practice_pool_status":"candidate" if depths["practice"] else "reflection_only" if items else "missing",
            "transfer_pool_status":"candidate_requires_independence_review" if depths["transfer"] else "not_scored_reflection" if topic["assessment_route"]=="reflection" else "missing",
            "recall_pool_status":"candidate" if depths["recall"] else "not_scored_reflection" if topic["assessment_route"]=="reflection" else "missing",
            "interview_eligibility":"candidate_only" if depths["interview"] else "unscored_rehearsal" if topic["assessment_route"]=="reflection" else "no_pool",
            "validation_state":"validated_candidate" if len(validated)==2 else "not_validated",
            "human_review_state":"not_reviewed","publication_status":"unpublished","outstanding_errors":errors})
    assert len(rows)==157 and len({r["topic_key"] for r in rows})==157
    result={"format_version":1,"scope_sha256":digest(scope),"as_of":"2026-10-22","publication_basis":"No Phase 5 approvals/releases exist; baseline learner DB has no release records. Candidate validation is not publication.",
            "totals":{"topics":len(rows),"candidate_lessons":sum(r["lesson_bundle_status"]=="candidate" for r in rows),"validated_topic_pairs":sum(r["validation_state"]=="validated_candidate" for r in rows),"published_lessons":0,"human_reviews":0},"topics":rows}
    destination=REPO_ROOT/"data/placement-foundations-coverage.json";destination.write_text(json.dumps(result,indent=2,ensure_ascii=False)+"\n",encoding="utf-8")
    lines=["# Final content coverage", "", "Generated by `python -m scripts.placement_inventory` from the immutable 157-topic scope and exact candidate/report hashes. The companion `data/placement-foundations-coverage.json` contains every field and source reference. This is a shipping inventory, not approval or completed learning.", "",
           f"{result['totals']['candidate_lessons']} lesson candidates; {result['totals']['validated_topic_pairs']} validated lesson/pool pairs; **0 human reviews and 0 approved/published Placement Foundations lessons**. Remaining topics are explicitly un-authored; outlines never count as teaching.","",
           "The 53 historical lessons and 110 historical Arena problems retain legacy provenance. Subject-corpus links in JSON are editorial references only; no topic equivalence or new binding is inferred. Adapted Exercism items and corrected Two Sum retain their existing approval blockers.","",
           "Guided and independent practice are separate authored items in each initial objective pool. Transfer has a separate proposed family/context, pending human independence review. Reflection has no scored transfer/recall denominator. Candidate depths never imply runtime availability.",""]
    for subject in dict.fromkeys(r["subject"] for r in rows):
        selected=[r for r in rows if r["subject"]==subject];lines += ["## "+subject,"",f"{len(selected)} scope topics; {sum(r['lesson_bundle_status']=='candidate' for r in selected)} lesson candidates; 0 reviewed/published.",""]
        for row in selected:
            lines += [f"### Level {row['level']} — {row['title']} (`{row['topic_key']}`)","",
                      "- Competencies: "+"; ".join(row["competencies_required"]),
                      "- Prerequisites: "+(", ".join(row["prerequisites"]) or "None in the confirmed scope definition"),
                      "- Historical material: "+str(len(row["historical_material"]["subject_corpus"]))+" subject-corpus lessons; no reviewed mapping to this topic.",
                      "- Teaching: "+row["lesson_bundle_status"]+". Source/claim review: pending; reference URL and usage classification in JSON.",
                      "- Candidate objective depths (practice / transfer / recall / interview): "+" / ".join(str(row["candidate_pool_depth"][p]) for p in ["practice","transfer","recall","interview"])+". Published depths: 0 / 0 / 0 / 0.",
                      "- Validation: "+row["validation_state"]+". Human review: not reviewed. Publication: unpublished.",
                      "- Gaps: "+"; ".join(row["outstanding_errors"]),""]
    (REPO_ROOT/"docs/forge-v1/FINAL_CONTENT_COVERAGE.md").write_text("\n".join(lines)+"\n",encoding="utf-8")
    return result


if __name__=="__main__":print(json.dumps(inventory()["totals"]))
